patch:
diff --git a/repro/no-unused-expressions-use-strict.js b/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..529b4f6
--- /dev/null
+++ b/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,26 @@
+"use strict";
+// Repro: no-unused-expressions reports 'use strict' under ecmaVersion 3 (core-js config) in 9.25.0.
+// Usage: node repro/no-unused-expressions-use-strict.js [path/to/other/eslint/package]
+const path = require("node:path");
+const pkgDir = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "..");
+const { Linter } = require(path.join(pkgDir, "lib/api"));
+const version = require(path.join(pkgDir, "package.json")).version;
+
+const code = "'use strict';\nfunction f() {\n  'use strict';\n  return 1;\n}\nf();\n";
+// core-js options at report time (current core-js master also sets ignoreDirectives, which 9.25.0 does not know)
+const coreJsOptions = { allowShortCircuit: true, allowTernary: true, allowTaggedTemplates: true };
+
+const linter = new Linter({ configType: "flat" });
+let bad = 0;
+for (const ecmaVersion of [3, 5, "latest"]) {
+	for (const options of [coreJsOptions, {}]) {
+		const msgs = linter.verify(code, [{
+			languageOptions: { ecmaVersion, sourceType: "script" },
+			rules: { "no-unused-expressions": ["error", options] },
+		}], "x.js");
+		const label = `ecmaVersion=${String(ecmaVersion).padEnd(6)} options=${options === coreJsOptions ? "core-js" : "default"}`;
+		console.log(`eslint ${version} ${label}: ${msgs.length ? msgs.map(m => `${m.line}:${m.column} ${m.message}`).join(" | ") : "no errors"}`);
+		if (msgs.length) bad++;
+	}
+}
+process.exitCode = bad ? 1 : 0;
